const c="https://click2itbd.com";async function t(n,s={}){const i=c.replace(/\/+$/,"");let e=n.startsWith("/")?n:`/${n}`;i.endsWith("/api")&&e.startsWith("/api/")&&(e=e.slice(4));const a=`${i}${e}`,o=await fetch(a,{...s,headers:{"Content-Type":"application/json",...s.headers||{}}});if(!o.ok){const r=await o.json().catch(()=>({error:"Network error"}));throw new Error(r.error||`HTTP ${o.status}`)}return o.json()}async function p(n){return(await t("/api/domains/check",{method:"POST",body:JSON.stringify({domains:n})})).data}async function u(n){return(await t("/api/domains/suggestions",{method:"POST",body:JSON.stringify({domain:n})})).data||[]}async function g(){return(await t("/api/domains/pricing")).data}async function d(n){const s=await t("/api/hosting/usage",{method:"POST",body:JSON.stringify({providerAccountId:n})});if(!s.success)throw new Error("Failed to get hosting usage");return s.data}async function h(n){return await t("/api/hosting/provision",{method:"POST",body:JSON.stringify(n)})}async function y(n){return await t("/api/hosting/suspend",{method:"POST",body:JSON.stringify({providerAccountId:n})})}async function f(n){return await t("/api/hosting/unsuspend",{method:"POST",body:JSON.stringify({providerAccountId:n})})}async function S(n){return await t("/api/hosting/terminate",{method:"POST",body:JSON.stringify({providerAccountId:n})})}async function m(n,s){return await t("/api/hosting/change-package",{method:"POST",body:JSON.stringify({providerAccountId:n,newPlanCode:s})})}export{u as a,g as b,p as c,m as d,d as g,h as p,y as s,S as t,f as u};
